import{_ as i,o as t,c as a,ag as o}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/smtp-config.png",s="/nada-documentation/images/gmail-email-config.png",r="/nada-documentation/images/smtp-settings.png",l="/nada-documentation/images/forgot-password.png",_=JSON.parse('{"title":"Email configurations","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/configurations/email.md","filePath":"installation-guide/configurations/email.md","lastUpdated":1786379412000}'),p={name:"installation-guide/configurations/email.md"};function c(m,e,d,g,u,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="email-configurations" tabindex="-1">Email configurations <a class="header-anchor" href="#email-configurations" aria-label="Permalink to &quot;Email configurations&quot;">​</a></h1><p>For SMTP drivers, SendGrid, and troubleshooting, see also <a href="./email-advanced.html">Email (advanced)</a>.</p><p>For the NADA to function correctly it is important that this step be completed.</p><p>Many of the functions within the NADA – such as registration and applying for access to datasets require that the NADA be able to send emails to users.</p><p>There are two ways to setup your email configurations. 1) Create a email.php file in the application/config folder 2) Edit email settings on the site configurations page.</p><h2 id="_1-configure-email-via-email-config-file" tabindex="-1">1. Configure email via email config file <a class="header-anchor" href="#_1-configure-email-via-email-config-file" aria-label="Permalink to &quot;1. Configure email via email config file&quot;">​</a></h2><p>A. Open the file application/config/email.php in notepad</p><p>B. Fill in the section using SMTP server with authentication enabled highlighted in below image</p><p><img src="'+n+'" alt=""></p><p>C. For Gmail user will have to fill the gmail smtp section shown as below</p><p><img src="'+s+'" alt=""></p><p>D. Save file</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Using a file for email configuration disable the email configuration page from the site administration.</p></div><h2 id="_2-configure-email-via-site-administration" tabindex="-1">2. Configure email via site administration <a class="header-anchor" href="#_2-configure-email-via-site-administration" aria-label="Permalink to &quot;2. Configure email via site administration&quot;">​</a></h2><p>A. Login to your NADA as an administrator</p><p>B. Go to Site administration, click on the Settings menu and choose “Settings”</p><p>C. Find the section “SMTP settings”</p><p><img src="'+r+'" alt=""></p><p>D. If the PHP/web server is configured to send email using PHP’s MAIL function, select the first option and don’t fill in anything else.</p><p>If your organization has a mail server and has have a dedicated account that can be setup for NADA, use the following settings: Check the radio button “Use SMTP Server”</p><p>E. Enter the host name for the server</p><p>F. Enter the port used by the server to send mail</p><p>G. If required, enter the user name used to send mail on the server</p><p>H. Enter the password used to send mail on the server</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>If the organization does not own a mail server, a Gmail account can be configured to be used with NADA.</p></div><ul><li><p>Check the radio button “Use SMTP Server”</p></li><li><p>Host name: ssl://smtp.googlemail.com or ssl://smtp.gmail.com</p></li><li><p>SMTP port: 465</p></li><li><p>Account username: <a href="mailto:email-address@gmail.com" target="_blank" rel="noreferrer">email-address@gmail.com</a></p></li><li><p>Account password: password for the gmail account</p></li></ul><p><strong>Test the email settings</strong></p><p>The quickest way to test if the email settings are working is to use the “forgot password” option from the user login page.</p><ul><li>Click on forgot password</li></ul><p><img src="'+l+'" alt=""></p><ul><li><p>Enter the administrator or any other accounts email address.</p></li><li><p>Check to the email account the mail was sent to.</p></li><li><p>If no mail is received the settings are wrong and need to be corrected.</p></li></ul>',31)])])}const v=i(p,[["render",c]]);export{_ as __pageData,v as default};
